void SharesheetInterceptorForTesting::ShowBubble(const std::string& window_id, ::sharesheet::LaunchSource source, ::crosapi::mojom::IntentPtr intent, ShowBubbleCallback callback) {
  GetForwardingInterface()->ShowBubble(std::move(window_id), std::move(source), std::move(intent), std::move(callback));
}
