SharesheetAsyncWaiter::SharesheetAsyncWaiter(
    Sharesheet* proxy) : proxy_(proxy) {}

SharesheetAsyncWaiter::~SharesheetAsyncWaiter() = default;

void SharesheetAsyncWaiter::ShowBubble(
    const std::string& window_id, ::sharesheet::LaunchSource source, ::crosapi::mojom::IntentPtr intent, ::sharesheet::SharesheetResult* out_sharesheet_result) {
  base::RunLoop loop;
  proxy_->ShowBubble(std::move(window_id),std::move(source),std::move(intent),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::sharesheet::SharesheetResult* out_sharesheet_result
,
             ::sharesheet::SharesheetResult sharesheet_result) {*out_sharesheet_result = std::move(sharesheet_result);
            loop->Quit();
          },
          &loop,
          out_sharesheet_result));
  loop.Run();
}

::sharesheet::SharesheetResult SharesheetAsyncWaiter::ShowBubble(
    const std::string& window_id, ::sharesheet::LaunchSource source, ::crosapi::mojom::IntentPtr intent) {
  ::sharesheet::SharesheetResult async_wait_result;
  ShowBubble(std::move(window_id),std::move(source),std::move(intent),&async_wait_result);
  return async_wait_result;
}

void SharesheetAsyncWaiter::ShowBubbleWithOnClosed(
    const std::string& window_id, ::sharesheet::LaunchSource source, ::crosapi::mojom::IntentPtr intent) {
  base::RunLoop loop;
  proxy_->ShowBubbleWithOnClosed(std::move(window_id),std::move(source),std::move(intent),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}








